  pgal (snd p) -> lr_lo r <= r_base r + snd p ->
  (s_areas stY) !! p = None -> (forall j, 0 <= j < NSLOTS -> (s_metas stY) !! (aadd p (AREA_HDR + META_SIZE * j)) = None) ->
